CREATE TYPE "CustomerTokenPurpose" AS ENUM ('EMAIL_VERIFICATION', 'PASSWORD_RESET');
CREATE TYPE "CustomerJobType" AS ENUM ('DATA_EXPORT', 'ACCOUNT_DELETION');
CREATE TYPE "CustomerJobStatus" AS ENUM ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED');
CREATE TYPE "CustomerAnalyticsEventType" AS ENUM ('PAGE_VIEW', 'DOCTOR_STARTED', 'DOCTOR_COMPLETED', 'PRODUCT_VIEWED', 'FAVORITE_CHANGED', 'ACCOUNT_CREATED');
CREATE TABLE "Customer" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "displayName" TEXT NOT NULL, "locale" TEXT NOT NULL DEFAULT 'ar-EG', "emailVerifiedAt" TIMESTAMP(3), "active" BOOLEAN NOT NULL DEFAULT true, "historyOptIn" BOOLEAN NOT NULL DEFAULT false, "imageSavingOptIn" BOOLEAN NOT NULL DEFAULT false, "analyticsOptIn" BOOLEAN NOT NULL DEFAULT false, "marketingOptIn" BOOLEAN NOT NULL DEFAULT false, "deletionRequestedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "CustomerSession" ("id" TEXT PRIMARY KEY, "customerId" TEXT NOT NULL, "tokenHash" TEXT NOT NULL UNIQUE, "userAgent" TEXT, "ipHash" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3));
CREATE TABLE "CustomerToken" ("id" TEXT PRIMARY KEY, "customerId" TEXT NOT NULL, "purpose" "CustomerTokenPurpose" NOT NULL, "tokenHash" TEXT NOT NULL UNIQUE, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CustomerDiagnosis" ("id" TEXT PRIMARY KEY, "customerId" TEXT NOT NULL, "summary" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CustomerSavedPlant" ("customerId" TEXT NOT NULL, "plantId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("customerId", "plantId"));
CREATE TABLE "CustomerProductFavorite" ("customerId" TEXT NOT NULL, "productId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("customerId", "productId"));
CREATE TABLE "CustomerSavedImage" ("id" TEXT PRIMARY KEY, "customerId" TEXT NOT NULL, "storageKey" TEXT NOT NULL UNIQUE, "contentType" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CustomerJob" ("id" TEXT PRIMARY KEY, "customerId" TEXT, "type" "CustomerJobType" NOT NULL, "status" "CustomerJobStatus" NOT NULL DEFAULT 'PENDING', "result" JSONB, "errorCode" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "startedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3));
CREATE TABLE "CustomerAuditLog" ("id" TEXT PRIMARY KEY, "customerId" TEXT, "actorType" TEXT NOT NULL, "action" TEXT NOT NULL, "targetType" TEXT NOT NULL, "targetId" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AnalyticsEvent" ("id" TEXT PRIMARY KEY, "eventType" "CustomerAnalyticsEventType" NOT NULL, "occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "anonymousIdHash" TEXT NOT NULL, "locale" TEXT, "route" TEXT, "dimensions" JSONB);
CREATE TABLE "AnalyticsDailyRollup" ("id" TEXT PRIMARY KEY, "date" TIMESTAMP(3) NOT NULL, "eventType" "CustomerAnalyticsEventType" NOT NULL, "locale" TEXT NOT NULL DEFAULT 'all', "count" INTEGER NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Customer_active_idx" ON "Customer"("active"); CREATE INDEX "Customer_createdAt_idx" ON "Customer"("createdAt"); CREATE INDEX "CustomerSession_customerId_expiresAt_idx" ON "CustomerSession"("customerId", "expiresAt"); CREATE INDEX "CustomerToken_customerId_purpose_expiresAt_idx" ON "CustomerToken"("customerId", "purpose", "expiresAt"); CREATE INDEX "CustomerDiagnosis_customerId_createdAt_idx" ON "CustomerDiagnosis"("customerId", "createdAt"); CREATE INDEX "CustomerSavedPlant_plantId_idx" ON "CustomerSavedPlant"("plantId"); CREATE INDEX "CustomerProductFavorite_productId_idx" ON "CustomerProductFavorite"("productId"); CREATE INDEX "CustomerSavedImage_expiresAt_idx" ON "CustomerSavedImage"("expiresAt"); CREATE INDEX "CustomerSavedImage_customerId_idx" ON "CustomerSavedImage"("customerId"); CREATE INDEX "CustomerJob_status_createdAt_idx" ON "CustomerJob"("status", "createdAt"); CREATE INDEX "CustomerJob_customerId_type_idx" ON "CustomerJob"("customerId", "type"); CREATE INDEX "CustomerAuditLog_customerId_createdAt_idx" ON "CustomerAuditLog"("customerId", "createdAt"); CREATE INDEX "CustomerAuditLog_action_createdAt_idx" ON "CustomerAuditLog"("action", "createdAt"); CREATE INDEX "AnalyticsEvent_eventType_occurredAt_idx" ON "AnalyticsEvent"("eventType", "occurredAt"); CREATE INDEX "AnalyticsEvent_occurredAt_idx" ON "AnalyticsEvent"("occurredAt"); CREATE UNIQUE INDEX "AnalyticsDailyRollup_date_eventType_locale_key" ON "AnalyticsDailyRollup"("date", "eventType", "locale"); CREATE INDEX "AnalyticsDailyRollup_date_idx" ON "AnalyticsDailyRollup"("date");
ALTER TABLE "CustomerSession" ADD FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE; ALTER TABLE "CustomerToken" ADD FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE; ALTER TABLE "CustomerDiagnosis" ADD FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE; ALTER TABLE "CustomerSavedPlant" ADD FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE; ALTER TABLE "CustomerSavedPlant" ADD FOREIGN KEY ("plantId") REFERENCES "Plant"("id") ON DELETE CASCADE; ALTER TABLE "CustomerProductFavorite" ADD FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE; ALTER TABLE "CustomerProductFavorite" ADD FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE; ALTER TABLE "CustomerSavedImage" ADD FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE; ALTER TABLE "CustomerJob" ADD FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE SET NULL; ALTER TABLE "CustomerAuditLog" ADD FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE SET NULL;
